package com.bank.reward.service;

import java.util.logging.Logger;

// Rolling bottom-up Fibonacci: constant space dynamic programming.
public class RewardProjectionService {
    private static final Logger log = Logger.getLogger(RewardProjectionService.class.getName());

    public long projectedTarget(int month) {
        if (month < 0) throw new IllegalArgumentException("month must be >= 0");
        if (month == 0) return 0;
        long prev2 = 0, prev1 = 1;                        // base cases
        for (int i = 2; i <= month; i++) {
            long cur = prev1 + prev2;                     // sum of previous two
            prev2 = prev1;                                // roll the window forward
            prev1 = cur;
        }
        final long result = prev1;
        log.info(() -> "Projected reward target for month " + month + " = " + result);
        return prev1;
    }
}
